const KrysDirectory = (() => {
  function all() {
    return KRYS_CENTERS_DB;
  }

  function getById(id) {
    return KRYS_CENTERS_DB.find(c => c.id === id) || KRYS_CENTERS_DB[0];
  }

  function search(query) {
    if (!query || !query.trim()) return KRYS_CENTERS_DB;
    const q = query.trim().toLowerCase();
    return KRYS_CENTERS_DB.filter(c =>
      c.city.toLowerCase().includes(q) ||
      c.postalCode.startsWith(q) ||
      c.department === q ||
      c.region.toLowerCase().includes(q) ||
      c.name.toLowerCase().includes(q) ||
      c.address.toLowerCase().includes(q) ||
      c.audiologist.toLowerCase().includes(q)
    );
  }

  function byRegion() {
    const map = {};
    KRYS_CENTERS_DB.forEach(c => {
      if (!map[c.region]) map[c.region] = [];
      map[c.region].push(c);
    });
    return map;
  }

  function findNearest(lat, lng) {
    if (!lat || !lng) return KRYS_CENTERS_DB[0];
    let best = KRYS_CENTERS_DB[0], minD = Infinity;
    KRYS_CENTERS_DB.forEach(c => {
      const d = Math.hypot(c.lat - lat, (c.lng - lng) * Math.cos(lat * Math.PI / 180));
      if (d < minD) { minD = d; best = c; }
    });
    return best;
  }

  return { all, getById, search, byRegion, findNearest };
})();